#include "ui.h"
#include "../app/hmi_app.h"

/**
 * Copia el valor visual al spinbox solo si difiere, evitando actualizaciones
 * redundantes. La aplicacion conserva ademas dirty y el valor confirmado.
 */
void sincronizarUmbralDesdeSlider(lv_event_t * e)
{
    (void)e;
    int32_t valor = lv_slider_get_value(ui_sldUmbralHumedad);
    if(lv_spinbox_get_value(ui_spnUmbralHumedad) != valor)
        lv_spinbox_set_value(ui_spnUmbralHumedad, valor);
}

/**
 * Recorrido inverso de sincronizacion visual; no transmite UMBRAL.
 */
void sincronizarUmbralDesdeSpinbox(lv_event_t * e)
{
    (void)e;
    int32_t valor = lv_spinbox_get_value(ui_spnUmbralHumedad);
    if(lv_slider_get_value(ui_sldUmbralHumedad) != valor)
        lv_slider_set_value(ui_sldUmbralHumedad, valor, LV_ANIM_OFF);
}

/**
 * Delega apertura del editor propio. El cliente decide si hay enlace y
 * si otra modificacion pendiente impide iniciar una nueva.
 */
void openAddEventPopup(lv_event_t * e)
{
    hmi_app_abrir_evento(e);
}

void aplicarUmbralHumedad(lv_event_t * e)
{
    hmi_app_aplicar_umbral(e);
}

void cargarHistorial(lv_event_t * e)
{
    hmi_app_cargar_historial(e);
}

void actualizarHistorial(lv_event_t * e)
{
    hmi_app_actualizar_historial(e);
}
